use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_healthy: bool,
  pub api_echo: Option<i32>,
  pub api_alert_result: Option<bool>,
  pub api_ack: Option<u8>,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_healthy(container.api_healthy);
  put_echo(container.api_echo);
  put_alert_result(container.api_alert_result);
  put_ack(container.api_ack);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  healthy: bool,
  echo: Option<i32>,
  alert_result: Option<bool>,
  ack: Option<u8>)
{
  put_healthy(healthy);
  put_echo(echo);
  put_alert_result(alert_result);
  put_ack(ack);
}

/// setter for IN DataPort
pub fn put_healthy(value: bool)
{
  *extern_api::IN_healthy.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN EventDataPort
pub fn put_echo(value: Option<i32>)
{
  *extern_api::IN_echo.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// setter for IN EventDataPort
pub fn put_alert_result(value: Option<bool>)
{
  *extern_api::IN_alert_result.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// setter for IN EventPort
pub fn put_ack(value: Option<u8>)
{
  *extern_api::IN_ack.lock().unwrap_or_else(|e| e.into_inner()) = value
}
